/* Private pipe transport with bounded I/O; no host-global signal changes. */
extern char **environ;
typedef struct {int input,output;pid_t process;float*buffer;U channels,rate,latency;int failed,ready;} Service;
/* poll() bounds every POSIX read/write; no watchdog thread is needed. */
static void service_deadline(Service*s,U timeout){}
static int pipe_transfer(int fd,void*data,U size,int writing,U timeout){unsigned char*p=data;uint64_t deadline=GetTickCount64()+timeout;while(size){int left=(int)(deadline-GetTickCount64());if(left<=0)return 0;struct pollfd descriptor={fd,writing?POLLOUT:POLLIN,0};int result=poll(&descriptor,1,left);if(result<0&&errno==EINTR)continue;if(result<=0)return 0;ssize_t done=writing?write(fd,p,size):read(fd,p,size);if(done<0&&(errno==EINTR||errno==EAGAIN))continue;if(done<=0)return 0;p+=done;size-=done;}return 1;}
static int pipe_write(int fd,const void*data,U size){sigset_t block,previous,pending;sigemptyset(&block);sigaddset(&block,SIGPIPE);pthread_sigmask(SIG_BLOCK,&block,&previous);sigpending(&pending);int existed=sigismember(&pending,SIGPIPE);int result=pipe_transfer(fd,(void*)data,size,1,5000);if(!result&&!existed){sigpending(&pending);if(sigismember(&pending,SIGPIPE)){int signal;sigwait(&block,&signal);}}pthread_sigmask(SIG_SETMASK,&previous,NULL);return result;}
static int pipe_read(int fd,void*data,U size,U timeout){return pipe_transfer(fd,data,size,0,timeout);}
static int response(Service*s,U operation,U frames,U channels,U timeout){U words[8];if(!pipe_read(s->output,words,32,timeout)||words[0]!=SERVICE_MAGIC||words[1]!=1||words[2]!=operation||words[3]!=0)return 0;if(operation==1&&(words[4]!=frames||words[5]!=channels))return 0;s->latency=words[7];return 1;}
static int service_command(Service*s,U operation,U arg0,U arg1,const void*payload,U size){if(s->failed)return 0;U words[5]={SERVICE_MAGIC,1,operation,arg0,arg1};if(!pipe_write(s->input,words,20)||(size&&!pipe_write(s->input,payload,size))||!response(s,operation,arg0,arg1,operation==7?30000:5000)){s->failed=1;return 0;}return 1;}
static void service_close(Service*s){if(s->process>0){if(s->ready&&!s->failed)service_command(s,4,0,0,NULL,0);close(s->input);close(s->output);pid_t result=waitpid(s->process,NULL,WNOHANG);if(result==0){kill(s->process,SIGTERM);uint64_t end=GetTickCount64()+1000;while((result=waitpid(s->process,NULL,WNOHANG))==0&&GetTickCount64()<end){struct timespec delay={0,1000000};nanosleep(&delay,NULL);}if(result==0){kill(s->process,SIGKILL);waitpid(s->process,NULL,0);}}}free(s->buffer);memset(s,0,sizeof(*s));}
static int service_start(Service*s){if(s->ready)return !s->failed;if(s->failed)return 0;if(config.flags&1){s->ready=1;return 1;}int input[2]={-1,-1},output[2]={-1,-1};if(pipe(input)||pipe(output))goto fail;for(int i=0;i<2;i++){fcntl(input[i],F_SETFD,FD_CLOEXEC);fcntl(output[i],F_SETFD,FD_CLOEXEC);}posix_spawn_file_actions_t actions;if(posix_spawn_file_actions_init(&actions))goto fail;posix_spawn_file_actions_adddup2(&actions,input[0],STDIN_FILENO);posix_spawn_file_actions_adddup2(&actions,output[1],STDOUT_FILENO);posix_spawn_file_actions_addopen(&actions,STDERR_FILENO,"/dev/null",O_WRONLY,0600);char command[16388];narrow(command,config.command,sizeof(command));char*argv[]={"sh","-c",command,NULL};int error=posix_spawn(&s->process,"/bin/sh",&actions,NULL,argv,environ);posix_spawn_file_actions_destroy(&actions);if(error){s->process=0;goto fail;}close(input[0]);input[0]=-1;close(output[1]);output[1]=-1;s->input=input[1];input[1]=-1;s->output=output[0];output[0]=-1;fcntl(s->input,F_SETFL,O_NONBLOCK);fcntl(s->output,F_SETFL,O_NONBLOCK);s->buffer=malloc(IO_FRAMES*2*4);if(!s->buffer||!response(s,0,0,0,30000))goto fail;s->ready=1;return 1;
fail:for(int i=0;i<2;i++){if(input[i]>=0)close(input[i]);if(output[i]>=0)close(output[i]);}service_close(s);s->failed=1;return 0;}
static int service_configure(Service*s,U rate,U channels){if(!service_start(s))return 0;if(s->rate==rate&&s->channels==channels)return 1;if(!(config.flags&1)&&!service_command(s,7,rate,channels,NULL,0))return 0;s->rate=rate;s->channels=channels;return 1;}
static int service_parameter(Service*s,U id,double value){int index=parameter_index(id);if(index<0)return 0;if(config.flags&1)return 1;return service_command(s,2,(U)index,8,&value,8);}
static int service_reset(Service*s){if(config.flags&1)return 1;return !s->ready||service_command(s,3,0,0,NULL,0);}
